"""Minimal-but-practical VT100/xterm emulator for observing TUI output."""
import re


class Cell:
    __slots__ = ('ch', 'fg', 'bg', 'bold', 'italic', 'under', 'rev', 'faint', 'strike')

    def __init__(self):
        self.ch = ' '
        self.fg = None
        self.bg = None
        self.bold = False
        self.italic = False
        self.under = False
        self.rev = False
        self.faint = False
        self.strike = False

    def copy_style(self, o):
        self.fg = o.fg
        self.bg = o.bg
        self.bold = o.bold
        self.italic = o.italic
        self.under = o.under
        self.rev = o.rev
        self.faint = o.faint
        self.strike = o.strike

    def style_key(self):
        return (self.fg, self.bg, self.bold, self.italic, self.under, self.rev,
                self.faint, self.strike)


def wcwidth(ch):
    o = ord(ch)
    if o == 0:
        return 0
    if 0x0300 <= o <= 0x036F:
        return 0
    # rough wide ranges
    for lo, hi in ((0x1100, 0x115F), (0x2E80, 0xA4CF), (0xAC00, 0xD7A3),
                   (0xF900, 0xFAFF), (0xFE30, 0xFE6F), (0xFF00, 0xFF60),
                   (0xFFE0, 0xFFE6), (0x1F300, 0x1F9FF), (0x20000, 0x2FFFD)):
        if lo <= o <= hi:
            return 2
    return 1


class Screen:
    def __init__(self, rows=24, cols=80):
        self.rows = rows
        self.cols = cols
        self.grid = [[Cell() for _ in range(cols)] for _ in range(rows)]
        self.alt = None
        self.cx = 0
        self.cy = 0
        self.cur = Cell()
        self.saved = None
        self.top = 0
        self.bot = rows - 1
        self.in_alt = False
        self.wrap_pending = False
        self.title = None
        self.osc_out = []
        self.cursor_visible = True
        self.mouse_modes = set()
        self.bracketed_paste = False
        self.scrollback = []

    # ---- helpers
    def blank_row(self):
        return [Cell() for _ in range(self.cols)]

    def clear_cell(self, c):
        c.ch = ' '
        c.copy_style(Cell())
        # background color persists in real terminals for ECH/ED with bg set;
        # keep simple: reset
        c.bg = self.cur.bg

    def feed(self, data):
        if isinstance(data, bytes):
            data = data.decode('utf-8', 'replace')
        i = 0
        n = len(data)
        while i < n:
            ch = data[i]
            if ch == '\x1b':
                consumed = self.esc(data, i)
                if consumed is None:
                    i += 1
                else:
                    i = consumed
                continue
            i += 1
            o = ord(ch)
            if o == 0x0d:
                self.cx = 0
                self.wrap_pending = False
            elif o == 0x0a or o == 0x0b or o == 0x0c:
                self.lf()
            elif o == 0x08:
                self.cx = max(0, self.cx - 1)
                self.wrap_pending = False
            elif o == 0x09:
                self.cx = min(self.cols - 1, (self.cx // 8 + 1) * 8)
            elif o == 0x07:
                pass
            elif o < 0x20:
                pass
            else:
                self.put(ch)

    def lf(self):
        self.wrap_pending = False
        if self.cy == self.bot:
            self.scroll_up(1)
        else:
            self.cy = min(self.rows - 1, self.cy + 1)

    def scroll_up(self, k):
        for _ in range(k):
            row = self.grid.pop(self.top)
            if self.top == 0 and not self.in_alt:
                self.scrollback.append(row)
            self.grid.insert(self.bot, self.blank_row())

    def scroll_down(self, k):
        for _ in range(k):
            self.grid.pop(self.bot)
            self.grid.insert(self.top, self.blank_row())

    def put(self, ch):
        w = wcwidth(ch)
        if self.wrap_pending:
            self.cx = 0
            self.lf()
            self.wrap_pending = False
        if self.cx >= self.cols:
            self.cx = 0
            self.lf()
        c = self.grid[self.cy][self.cx]
        c.ch = ch
        c.copy_style(self.cur)
        if w == 2 and self.cx + 1 < self.cols:
            c2 = self.grid[self.cy][self.cx + 1]
            c2.ch = ''
            c2.copy_style(self.cur)
            self.cx += 2
        else:
            self.cx += max(1, w)
        if self.cx >= self.cols:
            self.cx = self.cols - 1
            self.wrap_pending = True

    def esc(self, data, i):
        n = len(data)
        if i + 1 >= n:
            return None
        c = data[i + 1]
        if c == '[':
            m = re.compile(r'\x1b\[([\x30-\x3f]*)([\x20-\x2f]*)([\x40-\x7e])').match(data, i)
            if not m:
                return None
            self.csi(m.group(1), m.group(2), m.group(3))
            return m.end()
        if c == ']':
            j = data.find('\x07', i)
            k = data.find('\x1b\\', i)
            if j == -1 and k == -1:
                return None
            if j == -1 or (k != -1 and k < j):
                body = data[i + 2:k]
                end = k + 2
            else:
                body = data[i + 2:j]
                end = j + 1
            self.osc_out.append(body)
            if body.startswith('0;') or body.startswith('2;'):
                self.title = body[2:]
            return end
        if c in '()*+':
            return i + 3
        if c == '7':
            self.saved = (self.cx, self.cy, self.cur.style_key())
            return i + 2
        if c == '8':
            if self.saved:
                self.cx, self.cy = self.saved[0], self.saved[1]
            return i + 2
        if c == 'M':
            if self.cy == self.top:
                self.scroll_down(1)
            else:
                self.cy = max(0, self.cy - 1)
            return i + 2
        if c == 'D':
            self.lf()
            return i + 2
        if c == 'E':
            self.cx = 0
            self.lf()
            return i + 2
        if c == 'c':
            self.__init__(self.rows, self.cols)
            return i + 2
        if c == '=' or c == '>':
            return i + 2
        if c == 'P':  # DCS
            k = data.find('\x1b\\', i)
            return (k + 2) if k != -1 else None
        return i + 2

    def csi(self, params, inter, final):
        priv = params[:1] if params[:1] in '?><!' else ''
        ps = params[len(priv):]
        args = []
        for p in ps.split(';'):
            if p == '':
                args.append(None)
            else:
                try:
                    args.append(int(p))
                except ValueError:
                    args.append(None)
        def a(k, d=1):
            if k < len(args) and args[k] is not None:
                return args[k]
            return d

        if final == 'H' or final == 'f':
            self.cy = min(self.rows - 1, max(0, a(0, 1) - 1))
            self.cx = min(self.cols - 1, max(0, a(1, 1) - 1))
            self.wrap_pending = False
        elif final == 'A':
            self.cy = max(0, self.cy - a(0, 1)); self.wrap_pending = False
        elif final == 'B':
            self.cy = min(self.rows - 1, self.cy + a(0, 1)); self.wrap_pending = False
        elif final == 'C':
            self.cx = min(self.cols - 1, self.cx + a(0, 1)); self.wrap_pending = False
        elif final == 'D':
            self.cx = max(0, self.cx - a(0, 1)); self.wrap_pending = False
        elif final == 'E':
            self.cy = min(self.rows - 1, self.cy + a(0, 1)); self.cx = 0
        elif final == 'F':
            self.cy = max(0, self.cy - a(0, 1)); self.cx = 0
        elif final == 'G' or final == '`':
            self.cx = min(self.cols - 1, max(0, a(0, 1) - 1))
        elif final == 'd':
            self.cy = min(self.rows - 1, max(0, a(0, 1) - 1))
        elif final == 'J':
            mode = a(0, 0)
            if mode == 0:
                for x in range(self.cx, self.cols):
                    self.clear_cell(self.grid[self.cy][x])
                for y in range(self.cy + 1, self.rows):
                    for x in range(self.cols):
                        self.clear_cell(self.grid[y][x])
            elif mode == 1:
                for y in range(0, self.cy):
                    for x in range(self.cols):
                        self.clear_cell(self.grid[y][x])
                for x in range(0, self.cx + 1):
                    self.clear_cell(self.grid[self.cy][x])
            else:
                for y in range(self.rows):
                    for x in range(self.cols):
                        self.clear_cell(self.grid[y][x])
        elif final == 'K':
            mode = a(0, 0)
            if mode == 0:
                for x in range(self.cx, self.cols):
                    self.clear_cell(self.grid[self.cy][x])
            elif mode == 1:
                for x in range(0, self.cx + 1):
                    self.clear_cell(self.grid[self.cy][x])
            else:
                for x in range(self.cols):
                    self.clear_cell(self.grid[self.cy][x])
        elif final == 'L':
            k = a(0, 1)
            for _ in range(k):
                self.grid.pop(self.bot)
                self.grid.insert(self.cy, self.blank_row())
        elif final == 'M':
            k = a(0, 1)
            for _ in range(k):
                self.grid.pop(self.cy)
                self.grid.insert(self.bot, self.blank_row())
        elif final == 'P':
            k = a(0, 1)
            row = self.grid[self.cy]
            for _ in range(k):
                row.pop(self.cx)
                row.append(Cell())
        elif final == '@':
            k = a(0, 1)
            row = self.grid[self.cy]
            for _ in range(k):
                row.insert(self.cx, Cell())
                row.pop()
        elif final == 'X':
            k = a(0, 1)
            for x in range(self.cx, min(self.cols, self.cx + k)):
                self.clear_cell(self.grid[self.cy][x])
        elif final == 'r':
            self.top = max(0, a(0, 1) - 1)
            self.bot = min(self.rows - 1, a(1, self.rows) - 1)
            self.cx = 0
            self.cy = self.top
        elif final == 'S':
            self.scroll_up(a(0, 1))
        elif final == 'T':
            self.scroll_down(a(0, 1))
        elif final == 'm':
            self.sgr(args)
        elif final == 'h' or final == 'l':
            on = final == 'h'
            for v in args:
                if v is None:
                    continue
                if priv == '?':
                    if v == 1049 or v == 47 or v == 1047:
                        self.set_alt(on)
                    elif v == 25:
                        self.cursor_visible = on
                    elif v in (1000, 1002, 1003, 1006, 1015, 9):
                        if on:
                            self.mouse_modes.add(v)
                        else:
                            self.mouse_modes.discard(v)
                    elif v == 2004:
                        self.bracketed_paste = on
        elif final == 's':
            self.saved = (self.cx, self.cy, None)
        elif final == 'u':
            if self.saved:
                self.cx, self.cy = self.saved[0], self.saved[1]

    def set_alt(self, on):
        if on and not self.in_alt:
            self.alt = (self.grid, self.cx, self.cy)
            self.grid = [[Cell() for _ in range(self.cols)] for _ in range(self.rows)]
            self.in_alt = True
            self.cx = self.cy = 0
        elif not on and self.in_alt:
            self.grid, self.cx, self.cy = self.alt
            self.in_alt = False

    def sgr(self, args):
        if not args or all(x is None for x in args):
            args = [0]
        i = 0
        while i < len(args):
            v = args[i] if args[i] is not None else 0
            if v == 0:
                self.cur = Cell()
                self.cur.ch = ' '
            elif v == 1:
                self.cur.bold = True
            elif v == 2:
                self.cur.faint = True
            elif v == 3:
                self.cur.italic = True
            elif v == 4:
                self.cur.under = True
            elif v == 7:
                self.cur.rev = True
            elif v == 9:
                self.cur.strike = True
            elif v == 22:
                self.cur.bold = False; self.cur.faint = False
            elif v == 23:
                self.cur.italic = False
            elif v == 24:
                self.cur.under = False
            elif v == 27:
                self.cur.rev = False
            elif v == 29:
                self.cur.strike = False
            elif 30 <= v <= 37:
                self.cur.fg = v - 30
            elif v == 39:
                self.cur.fg = None
            elif 40 <= v <= 47:
                self.cur.bg = v - 40
            elif v == 49:
                self.cur.bg = None
            elif 90 <= v <= 97:
                self.cur.fg = v - 90 + 8
            elif 100 <= v <= 107:
                self.cur.bg = v - 100 + 8
            elif v == 38 or v == 48:
                if i + 1 < len(args) and args[i + 1] == 5:
                    col = args[i + 2] if i + 2 < len(args) else 0
                    if v == 38:
                        self.cur.fg = col
                    else:
                        self.cur.bg = col
                    i += 2
                elif i + 1 < len(args) and args[i + 1] == 2:
                    rgb = tuple(args[i + 2:i + 5])
                    if v == 38:
                        self.cur.fg = rgb
                    else:
                        self.cur.bg = rgb
                    i += 4
            i += 1

    def render(self, strip=True):
        lines = []
        for row in self.grid:
            s = ''.join(c.ch for c in row)
            lines.append(s.rstrip() if strip else s)
        while lines and lines[-1] == '':
            lines.pop()
        return '\n'.join(lines)

    def render_styled(self):
        """Render with inline style markers: {fg,bg,attrs}text"""
        out = []
        for row in self.grid:
            parts = []
            last = None
            for c in row:
                k = c.style_key()
                if k != last:
                    desc = []
                    if c.fg is not None:
                        desc.append('fg=%s' % (c.fg,))
                    if c.bg is not None:
                        desc.append('bg=%s' % (c.bg,))
                    for nm in ('bold', 'italic', 'under', 'rev', 'faint', 'strike'):
                        if getattr(c, nm):
                            desc.append(nm)
                    parts.append('⟨%s⟩' % (','.join(desc) if desc else '-'))
                    last = k
                parts.append(c.ch)
            line = ''.join(parts)
            out.append(line)
        while out and re.sub(r'⟨[^⟩]*⟩', '', out[-1]).strip() == '':
            out.pop()
        return '\n'.join(out)

